/// One Appendix C / F case; the balances are before the fee, the anchors and the HTLCs. `htlc_ids` index
/// `test_htlcs`. `htlc_txs` are the signed HTLC transactions of the untrimmed HTLC outputs.
pub const Case = struct {
    name: []const u8,
    to_local_msat: u64,
    to_remote_msat: u64,
    dust_limit_satoshis: u64,
    feerate_per_kw: u32,
    htlc_ids: []const u8,
    commit_tx: []const u8,
    htlc_txs: []const []const u8,
};

