pub const ZfHtlc = struct { amount_msat: u64, payment_hash: []const u8, cltv_expiry: u32 };

pub const ZfCase = struct {
    name: []const u8,
    dust_limit_satoshis: u64,
    to_local_msat: u64,
    to_remote_msat: u64,
    /// Received by the commitment's owner.
    incoming: []const ZfHtlc,
    /// Offered by the owner.
    outgoing: []const ZfHtlc,
    commit_tx: []const u8,
    htlc_txs: []const []const u8,
};

